SELECT * FROM (SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, CASE WHEN balance >= 70000 THEN 'high' WHEN balance >= 16000 THEN 'mid' ELSE 'low' END AS balance_bucket, SORT_ARRAY(COLLECT_SET(account_type)) AS account_type_list, COUNT(DISTINCT balance) AS unique_statuss FROM accounts GROUP BY DATE_FORMAT(opened_date, 'yyyy-MM'), CASE WHEN balance >= 70000 THEN 'high' WHEN balance >= 16000 THEN 'mid' ELSE 'low' END) AS s WHERE unique_statuss > 8
